import Database from 'better-sqlite3';
import { drizzle, type BetterSQLite3Database } from 'drizzle-orm/better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import { app } from 'electron';
import { join } from 'node:path';
import * as schema from './schema.js';

export type Db = BetterSQLite3Database<typeof schema> & { $client: Database.Database };

// Generated by drizzle-kit at the repo root; resolved from dist/database/.
const MIGRATIONS_DIR = join(import.meta.dirname, '..', '..', 'drizzle');

let db: Db | undefined;

/** Opens <userData>/journey.db on first use and applies any pending migrations. */
export function getDb(): Db {
  if (db) return db;
  const sqlite = new Database(join(app.getPath('userData'), 'journey.db'));
  sqlite.pragma('journal_mode = WAL');
  sqlite.pragma('foreign_keys = ON');
  db = drizzle(sqlite, { schema });
  migrate(db, { migrationsFolder: MIGRATIONS_DIR });
  return db;
}

export function closeDb() {
  db?.$client.close();
  db = undefined;
}
